"""Minimal YAML renderer — standard library only."""

from . import PluginError, Renderer, register


def _yaml_value(v) -> str:
    """Serialize a scalar value to a YAML-safe string."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return str(v)
    if isinstance(v, str):
        # Quote if the value could be misinterpreted or contains special chars
        if v == "" or v in ("true", "false", "null", "yes", "no", "on", "off"):
            return '"' + v + '"'
        special = set(":{}[]&*?|->!%@`#,")
        if any(c in v for c in special):
            return '"' + v + '"'
        if v.startswith((" ", "\t")) or v.endswith((" ", "\t")):
            return '"' + v + '"'
        return v
    return str(v)


def _yaml_block(rows: list[dict]) -> str:
    """Render a list of flat dicts as a YAML block sequence."""
    if not rows:
        return ""
    keys = list(rows[0].keys())
    lines: list[str] = []
    for row in rows:
        lines.append("-")
        for k in keys:
            v = row.get(k)
            lines.append("  " + k + ": " + _yaml_value(v))
    return "\n".join(lines)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_block(rows) + "\n"

