"""Minimal YAML renderer — standard library only."""

from plugins import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Return a YAML-safe scalar string for *value*."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    s = str(value)
    # Quote strings that could be misinterpreted as YAML types
    if s.lower() in ("true", "false", "null", "yes", "no", "on", "off",
                      "y", "n", "yml", "yaml"):
        return f"'{s}'"
    if s == "" or s[0] in (" ", "\t", "'", '"', "{", "}", "[", "]",
                            ",", "&", "*", "?", "|", "-", "<", ">",
                            "=", "!", "%", "@", "`"):
        return f"'{s}'"
    return s


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        keys = list(rows[0].keys())
        lines: list[str] = []
        for row in rows:
            lines.append("-")
            for k in keys:
                lines.append(f"  {k}: {_yaml_scalar(row[k])}")
        return "\n".join(lines) + "\n"

